define(["jquery", "core/ajax", "core/notification"], function ($, Ajax, Notification) { var HeartbeatManager = function () { this.courseid = null; this.userid = null; this.interval = 25000; this.timer = null; this.lastHeartbeat = 0; this.enabled = false; this.sesskey = "" }; HeartbeatManager.prototype.init = function (courseid, userid, interval, sesskey) { this.courseid = courseid; this.userid = userid; this.interval = (interval || 25) * 1000; this.sesskey = sesskey || (M.cfg && M.cfg.sesskey) || ""; this.enabled = true; this.interval += Math.floor(Math.random() * 10000) - 5000; var stored = sessionStorage.getItem("manireports_last_heartbeat"); if (stored) { this.lastHeartbeat = parseInt(stored) } this.start(); this.sendHeartbeat(); var self = this; document.addEventListener("visibilitychange", function () { if (document.hidden) { self.stop() } else { self.start(); self.sendHeartbeat() } }); window.addEventListener("beforeunload", function () { self.stop() }) }; HeartbeatManager.prototype.start = function () { if (!this.enabled || this.timer) { return } var self = this; this.timer = setInterval(function () { self.sendHeartbeat() }, this.interval) }; HeartbeatManager.prototype.stop = function () { if (this.timer) { clearInterval(this.timer); this.timer = null } }; HeartbeatManager.prototype.sendHeartbeat = function () { if (!this.enabled) { return } if (!this.sesskey) { if (M.cfg && M.cfg.sesskey) { this.sesskey = M.cfg.sesskey } else { return } } var now = Math.floor(Date.now() / 1000); if (now - this.lastHeartbeat < 10) { return } var self = this; $.ajax({ url: M.cfg.wwwroot + "/local/manireports/ui/ajax/heartbeat.php", method: "POST", data: { courseid: this.courseid, userid: this.userid, timestamp: now, sesskey: this.sesskey }, dataType: "json", success: function (response) { if (response.success) { self.lastHeartbeat = now; sessionStorage.setItem("manireports_last_heartbeat", now) } }, error: function (xhr, status, error) { console.warn("Heartbeat failed:", error) } }) }; HeartbeatManager.prototype.disable = function () { this.enabled = false; this.stop() }; return { init: function (courseid, userid, interval, sesskey) { var manager = new HeartbeatManager; manager.init(courseid, userid, interval, sesskey); return manager } } });
